CREATE TABLE public.user_sessions (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version integer NOT NULL DEFAULT 0, user_id uuid NOT NULL REFERENCES public.users(id), identity_id uuid, client varchar(16) NOT NULL CHECK (client IN ('admin','mobile')), refresh_token_hash varchar(64) NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, ip text, user_agent text, last_active_at timestamptz NOT NULL DEFAULT now());
